dir$s321.prototype.beforeButtonDialogClick = function (id) {
  var p = this._dir, g = p.grid(0), dt = g.data;
  switch (id) {
    case 'ok':
		var d = p.valForm('ngay_hl'),d2 = p.valForm('ngay_hld');
		var k = $.date(d,"dd/mm/yy"),k2 = $.date(d2,"dd/mm/yy");
		if (p.valForm('ngay_hld') <= p.valForm('ngay_hl')) { 
			<!-- $.question('jkhj '+'Nhap sai ngay ??' ); -->
			<!-- $.showToast(p.msg('noDate')); -->

			$.alert(p.msg('noDate')+' ' + k + ' < ' + k2);			
			return false;
		}

		var dscong = p.valForm('ds_cong').trim();
		if (dscong == "") {
			$.showToast(p.msg('noSelectContainer'))
			p.jObject('ds_cong').focus(); 
			return false;
		}
		break;			
    default:
      break;
  }
  return true;
}
dir$s321.prototype.beforeButtonGridClick = function (id, gindex) {
  var p = this._dir;
  switch (id) {
	case '10':
       p.showFilter("s321C1", null, {_ngay_ct: p.valForm('ngay_ct')});	  
	  return false;
      break;
    default:
      break;
  }
  return true;
}

dir$s321.prototype.formFieldValueChange = function (o, cF, v) {
  var p = this._dir;
  switch (cF){
&VoucherExRateValid01;
    case 'ma_gd':
      dir$s321HiddenColumnByTran(p);
      break;
    case 'ma_ngv':
      dir$s321HiddenColumnByType(p);
      break;
    case 'ty_gia':
      p.calcExpressionAll(0, '!ty_gia');
      break;
    case 'ma_kh':
      p.request('Customer', '', ['ma_kh', 'ngay_ct', 'ma_nt']);
      break;
	case 'ma_noi_di':
      dir$s321HiddenColumnByDay(p);
      break;
	case 'ma_loai':
      //dir$s321HiddenColumnByGid(p);
      break;
	case 'ds_cong':
      dir$s321HiddenContGrid(p);
    break;
    default:
      break;
  }
}
&VoucherExRateValid02;
dir$s321.prototype.gridDetailActionChange = function(gindex, action, r){
  var p = this._dir;
  if (action == 'AfterDeleteRow' || action == 'AfterAppendGrid') dir$s321DisabledMasterField(p, p.grid(gindex));
  return true;
}
function dir$s321DisabledMasterField(p, g){
    if (p.options.action !="NEW") p.setDisabled(['ma_kh', 'so_ct','ngay_ct', 'ma_nt','ngay_ct','ty_gia'], true);
}
function dir$s321HiddenColumnByType(p){
  var v = p.valForm('ma_ngv'), nt = p.valForm('ma_nt'), bc = p.options.struct.baseCurrency;
}
