}
function dir$s321NewLoadTyGia(p){
	if(p.options.action  == 'NEW')
	{
		p.request('GetExRate', '', ['ma_nt', 'ngay_ct'], function(){
			p.calcExpressionAll(0, '!ty_gia');
		});
	}
}
function dir$s321HiddenContGrid(p){

  var dscong = p.valForm('ds_cong').trim();
  var arrayds = dscong.split(",");

  if(arrayds == "" && p.options.action  == 'NEW')
  {
  	p.setColumnHidden(0, ['gia_20GP', 'gia_40GP', 'gia_40HQ', 'gia_45HQ', 'gia_20RF', 'gia_40RF', 'gia_20OT', 'gia_40OT', 'gia_40HOT', 'gia_20FL', 'gia_40FL', 'gia_40HFL', 'gia_20TK', 'gia_40TK','gia2_20GP', 'gia2_40GP', 'gia2_40HQ', 'gia2_45HQ', 'gia2_20RF', 'gia2_40RF', 'gia2_20OT', 'gia2_40OT', 'gia2_40HOT', 'gia2_20FL', 'gia2_40FL', 'gia2_40HFL', 'gia2_20TK', 'gia2_40TK'], true);
  }
  else {

  if(arrayds)
  {

	if(arrayds.includes("20GP"))
		p.setColumnHidden(0, ['gia_20GP','gia2_20GP'], false);
	else
		p.setColumnHidden(0, ['gia_20GP','gia2_20GP'], true);


	if(arrayds.includes("40GP"))
		p.setColumnHidden(0, ['gia_40GP','gia2_40GP'], false);
	else
		p.setColumnHidden(0, ['gia_40GP','gia2_40GP'], true);


	if(arrayds.includes("40HQ"))
		p.setColumnHidden(0, ['gia_40HQ','gia2_40HQ'], false);
	else
		p.setColumnHidden(0, ['gia_40HQ','gia2_40HQ'], true);


	if(arrayds.includes("45HQ"))
		p.setColumnHidden(0, ['gia_45HQ','gia2_45HQ'], false);
	else
		p.setColumnHidden(0, ['gia_45HQ','gia2_45HQ'], true);


	if(arrayds.includes("20RF"))
		p.setColumnHidden(0, ['gia_20RF','gia2_20RF'], false);
	else
		p.setColumnHidden(0, ['gia_20RF','gia2_20RF'], true);

	if(arrayds.includes("40RF"))
		p.setColumnHidden(0, ['gia_40RF','gia2_40RF'], false);
	else
		p.setColumnHidden(0, ['gia_40RF','gia2_40RF'], true);


	if(arrayds.includes("20OT"))
		p.setColumnHidden(0, ['gia_20OT','gia2_20OT'], false);
	else
		p.setColumnHidden(0, ['gia_20OT','gia2_20OT'], true);


	if(arrayds.includes("40OT"))
		p.setColumnHidden(0, ['gia_40OT','gia2_40OT'], false);
	else
		p.setColumnHidden(0, ['gia_40OT','gia2_40OT'], true);


	if(arrayds.includes("40HOT"))
		p.setColumnHidden(0, ['gia_40HOT','gia2_40HOT'], false);
	else
		p.setColumnHidden(0, ['gia_40HOT','gia2_40HOT'], true);


	if(arrayds.includes("20FL"))
		p.setColumnHidden(0, ['gia_20FL','gia2_20FL'], false);
	else
		p.setColumnHidden(0, ['gia_20FL','gia2_20FL'], true);


	if(arrayds.includes("40FL"))
		p.setColumnHidden(0, ['gia_40FL','gia2_40FL'], false);
	else
		p.setColumnHidden(0, ['gia_40FL','gia2_40FL'], true);


	if(arrayds.includes("40HFL"))
		p.setColumnHidden(0, ['gia_40HFL','gia2_40HFL'], false);
	else
		p.setColumnHidden(0, ['gia_40HFL','gia2_40HFL'], true);

	if(arrayds.includes("20TK"))
		p.setColumnHidden(0, ['gia_20TK','gia2_20TK'], false);
	else
		p.setColumnHidden(0, ['gia_20TK','gia2_20TK'], true);


	if(arrayds.includes("40TK"))
		p.setColumnHidden(0, ['gia_40TK','gia2_40TK'], false);
	else
		p.setColumnHidden(0, ['gia_40TK','gia2_40TK'], true);
  }
} 

}
function dir$s321HiddenColumnByGid(p){
p.setColumnHidden(0, ['gia_20GP', 'gia_40GP', 'gia_40HQ', 'gia_45HQ', 'gia_20RF', 'gia_40RF', 'gia_20OT', 'gia_40OT', 'gia_40HOT', 'gia_20FL', 'gia_40FL', 'gia_40HFL', 'gia_20TK', 'gia_40TK'], false)
 var oLoai = p.valForm('ma_loai').trim();
	switch (oLoai) {
		case 'FL':
			p.setColumnHidden(0, ['gia_20GP', 'gia_40GP', 'gia_40HQ', 'gia_45HQ', 'gia_20RF', 'gia_40RF', 'gia_20OT', 'gia_40OT', 'gia_40HOT', 'gia_20TK', 'gia_40TK'], true);

		break;
		case 'GP':
			p.setColumnHidden(0, ['gia_20RF', 'gia_40RF', 'gia_20OT', 'gia_40OT', 'gia_40HOT', 'gia_20FL', 'gia_40FL', 'gia_40HFL', 'gia_20TK', 'gia_40TK'], true);

		break;
		case 'OT':
			p.setColumnHidden(0, ['gia_20GP', 'gia_40GP', 'gia_40HQ', 'gia_45HQ', 'gia_20RF', 'gia_40RF', 'gia_20FL', 'gia_40FL', 'gia_40HFL', 'gia_20TK', 'gia_40TK'], true);

		break;
		case 'RF':
			p.setColumnHidden(0, ['gia_20GP', 'gia_40GP', 'gia_40HQ', 'gia_45HQ', 'gia_20OT', 'gia_40OT', 'gia_40HOT', 'gia_20FL', 'gia_40FL', 'gia_40HFL', 'gia_20TK', 'gia_40TK'], true);

		break;
		case 'TK':
			p.setColumnHidden(0, ['gia_20GP', 'gia_40GP', 'gia_40HQ', 'gia_45HQ', 'gia_20RF', 'gia_40RF', 'gia_20OT', 'gia_40OT', 'gia_40HOT', 'gia_20FL', 'gia_40FL', 'gia_40HFL'], true);

		break;
		default:
			p.setColumnHidden(0, ['gia_20GP', 'gia_40GP', 'gia_40HQ', 'gia_45HQ', 'gia_20RF', 'gia_40RF', 'gia_20OT', 'gia_40OT', 'gia_40HOT', 'gia_20FL', 'gia_40FL', 'gia_40HFL', 'gia_20TK', 'gia_40TK'], false)
		break;
	}

}
